INSERT INTO `risk_evaluations` VALUES (1,6,7,'2026-07-25 11:31:33',78,'HIGH','The project is at high risk due to critical-path schedule delays in UAT and Go Live, compounded by multiple outstanding customer-side dependencies (VPN access, API credentials, and infrastructure) currently blocking key deliverables. Additionally, active evaluation of excluded items (such as SAP integration, mobile applications, and voice bots) presents a significant risk of scope creep without formal change control.','[\"Escalate the blocked customer dependencies (VPN connectivity, API credentials, and infrastructure details) to customer stakeholders immediately to unblock CRM Integration, UAT, and Go-Live activities.\", \"Implement strict change control protocols to address out-of-scope requests, requiring formal Change Requests and impact assessments for SAP Integration, Mobile Applications, and Voice Bot proposals.\", \"Re-baseline the timeline for UAT (currently delayed from 15 May 2026) and Production Deployment (currently delayed from 30 June 2026) to account for the downstream impacts of current delays.\"]','{\"in_scope\": {\"activities\": [{\"activity\": \"CRM Integration Development\", \"confidence\": 95, \"deliverable\": \"CRM Integration\", \"classification\": \"IN_SCOPE\"}, {\"activity\": \"Analytics Dashboard Development\", \"confidence\": 95, \"deliverable\": \"The Vendor shall develop an Analytics Dashboard\", \"classification\": \"IN_SCOPE\"}, {\"activity\": \"Knowledge Transfer Sessions Planning\", \"confidence\": 95, \"deliverable\": \"Knowledge Transfer\", \"classification\": \"IN_SCOPE\"}, {\"activity\": \"Begin CRM Integration Testing\", \"confidence\": 95, \"deliverable\": \"CRM Integration\", \"classification\": \"IN_SCOPE\"}]}, \"timeline\": {\"deliverables\": [{\"risk\": \"LOW\", \"blockers\": [\"The activity is fully aligned with the approved scope and milestone scheduled for 25 April 2026. However, a dependency risk exists because successful implementation relies on the customer providing VPN connectivity, API credentials, and required infrastructure before the configuration can take place, as outlined in the project assumptions.\"], \"delay_days\": 0, \"deliverable\": \"The Vendor shall configure Azure AD SSO by 25 April 2026\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"Rescheduling the User Acceptance Testing (UAT) activity directly threatens the baseline milestone date of 15 May 2026. A delay in UAT completion introduces a cascading risk that could compress the timeline for downstream activities, specifically the Go Live deployment scheduled for 30 June 2026.\"], \"delay_days\": 0, \"deliverable\": \"UAT\", \"expected_date\": \"Unknown\", \"current_status\": \"Delayed\", \"dependency_status\": \"DELAY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"Revising the schedule for the Go Live activity introduces a risk of delaying the baseline \'Production Deployment (Go Live)\' milestone set for 30 June 2026. Adjusting planned milestone dates directly threatens the project\'s critical path and final delivery timeline.\"], \"delay_days\": 0, \"deliverable\": \"Production Deployment (Go Live)\", \"expected_date\": \"Unknown\", \"current_status\": \"Delayed\", \"dependency_status\": \"DELAY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"The activity \'Provide Production Environment Details\' is highly dependent on the customer fulfilling the baseline assumption: \'Customer shall provide required infrastructure before implementation.\' This represents a dependency risk, as any delay in receiving these production details from the customer will directly impact the \'Production Deployment (Go Live)\' deliverable scheduled for 30 June 2026.\"], \"delay_days\": 0, \"deliverable\": \"Production Deployment (Go Live)\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"The activity \'Provide API Credentials\' is explicitly listed as a customer dependency under the project Assumptions (\'Customer shall provide API credentials\'). If the customer fails to deliver these credentials on time, it poses a risk to the schedule of dependent deliverables, particularly the CRM Integration milestone scheduled for 15 April 2026.\"], \"delay_days\": 0, \"deliverable\": \"CRM Integration\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"According to the baseline assumptions, \'Customer shall provide VPN connectivity.\' Therefore, enabling VPN connectivity is a critical dependency on the customer. If the customer fails to provide or enable this connectivity in a timely manner, it could delay subsequent implementation activities.\"], \"delay_days\": 0, \"deliverable\": \"Internal Support Portal\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"The activity \'Prepare UAT Environment\' is necessary to meet the UAT milestone scheduled for 15 May 2026. However, there is a key dependency risk as the baseline assumptions explicitly state that the customer is responsible for providing VPN connectivity and the \'required infrastructure before implementation\'. If the customer fails to deliver these dependencies on time, the environment preparation will be impacted.\"], \"delay_days\": 0, \"deliverable\": \"UAT\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}]}, \"out_of_scope\": {\"activities\": [{\"reason\": \"The activity involves evaluating an \'SAP Integration Request\'. SAP Integration is not mentioned in the approved baseline scope (the only approved integration is \'CRM Integration\'). According to the Change Control section, any work beyond the approved scope requires a formal Change Request approval, making this activity an unapproved out-of-scope request.\", \"activity\": \"Evaluate SAP Integration Request\", \"confidence\": 95, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"None\"}, {\"reason\": \"The activity \'Review Mobile Applications Request\' directly relates to native mobile applications. The provided baseline context explicitly excludes \'Native Android and iOS applications\' from the project scope. Reviewing or implementing mobile applications introduces a significant risk of scope creep, and any work beyond the approved scope requires a formal Change Request approval.\", \"activity\": \"Review Mobile Applications Request\", \"confidence\": 95, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"None (Explicitly Out of Scope)\"}, {\"reason\": \"The baseline context explicitly states that \'Voice Bot implementation is out of scope.\' Evaluating a Voice Bot proposal introduces activities related to an excluded item, posing a high risk of scope creep. According to the baseline, any work beyond the approved scope requires a formal Change Request approval.\", \"activity\": \"Evaluate Voice Bot Proposal\", \"confidence\": 95, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"Voice Bot implementation (Explicitly Out of Scope)\"}, {\"reason\": \"The activity involves assessing an \'SAP Integration Request\', which is not in the approved baseline scope. The scope explicitly defines \'CRM Integration\' and \'Azure AD SSO\' as the only approved integration deliverables. Any work related to SAP integration constitutes scope creep and requires a formal Change Request approval under the project\'s Change Control policy.\", \"activity\": \"Assess SAP Integration Request\", \"confidence\": 95, \"classification\": \"POSSIBLE_SCOPE_CREEP\", \"similar_deliverable\": \"None\"}]}}'),(2,6,7,'2026-07-26 09:58:28',82,'HIGH','The project is at high risk due to critical delays in key milestones like UAT and Go-Live, which are directly blocked by unresolved customer dependencies including VPN connectivity, API credentials, and required infrastructure. Furthermore, severe scope creep pressure from four unauthorized feature requests threatens to further de-rail the project timeline and resource allocation.','[\"Escalate the blocked customer deliverables (VPN, API credentials, and infrastructure) to project sponsors immediately to establish a hard deadline for resolution.\", \"Initiate a formal change management process to defer the out-of-scope requests (Analytics, SAP, Mobile, and Voice Bot) to a future phase or secure additional funding and timeline extensions.\", \"Conduct a schedule re-baselining session with key stakeholders to adjust and publish realistic dates for the UAT and Go-Live milestones.\", \"Review and formally align the 3 in-scope activities with the baseline document to ensure 100% agreement on core deliverables.\"]','{\"in_scope\": {\"activities\": [{\"activity\": \"CRM Integration Testing\", \"confidence\": 90, \"deliverable\": \"The Vendor shall implement CRM Integration by 15 April 2026.\", \"classification\": \"IN_SCOPE\"}, {\"activity\": \"Azure AD Single Sign-On Configuration\", \"confidence\": 90, \"deliverable\": \"The Vendor shall configure Azure AD SSO by 25 April 2026.\", \"classification\": \"IN_SCOPE\"}, {\"activity\": \"Knowledge Transfer Session Planning\", \"confidence\": 90, \"deliverable\": \"Knowledge Transfer - 05 July 2026\", \"classification\": \"IN_SCOPE\"}]}, \"timeline\": {\"deliverables\": [{\"risk\": \"MEDIUM\", \"blockers\": [\"Rescheduling UAT directly affects the project\'s baseline milestone of 15 May 2026.\"], \"delay_days\": 0, \"deliverable\": \"UAT - 15 May 2026\", \"expected_date\": \"Unknown\", \"current_status\": \"Delayed\", \"dependency_status\": \"DELAY\"}, {\"risk\": \"HIGH\", \"blockers\": [\"Revising the Go Live schedule indicates a risk of delaying the agreed milestone of 30 June 2026.\"], \"delay_days\": 0, \"deliverable\": \"Go Live - 30 June 2026\", \"expected_date\": \"Unknown\", \"current_status\": \"Delayed\", \"dependency_status\": \"DELAY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"This activity relies on the customer fulfilling an explicit project assumption.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide API credentials.\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"Fulfilling VPN connectivity is a critical customer assumption required before implementation.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide VPN connectivity.\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"Preparing the UAT environment is dependent on the customer providing the required infrastructure before implementation.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide required infrastructure before implementation.\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}]}, \"out_of_scope\": {\"activities\": [{\"reason\": \"Analytics Dashboard Development is not listed within the defined project scope in the baseline document.\", \"activity\": \"Analytics Dashboard Development\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"Analytics Dashboard Development\"}, {\"reason\": \"SAP Integration is not included in the defined project scope.\", \"activity\": \"SAP Integration Request Assessment\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"SAP Integration Request Assessment\"}, {\"reason\": \"The baseline project scope specifies a web-based portal; mobile applications are out of scope.\", \"activity\": \"Mobile Applications Request Review\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"Mobile Applications Request Review\"}, {\"reason\": \"Voice Bot functionality is not part of the defined project scope, which only includes AI Knowledge Search.\", \"activity\": \"Voice Bot Capability Evaluation\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"Voice Bot Capability Evaluation\"}]}}'),(3,6,7,'2026-07-26 16:44:05',72,'HIGH','The project faces critical schedule risks as key deliverables, including Azure AD SSO configuration, are currently blocked by pending customer dependencies such as VPN access and API credentials. This exposure is further compounded by multiple unapproved scope creep requests for SAP integration, mobile applications, and a voice bot, which threaten to dilute project resources.','[\"Escalate the pending customer deliverables (VPN connectivity, API credentials, and infrastructure setup) to client leadership to unblock the Azure AD SSO configuration.\", \"Initiate a formal Change Control process for the SAP Integration request to evaluate its impact on project budget and timeline.\", \"Formally decline the Mobile Applications request as it violates the web-only portal contract, or propose it as a separate phase under a new Statement of Work.\", \"Decline or defer the Voice Bot implementation, logging it as a post-go-live backlog item to protect the current phase\'s timeline.\"]','{\"in_scope\": {\"activities\": [{\"activity\": \"CRM Integration\", \"confidence\": 90, \"match_type\": \"substring\", \"deliverable\": \"The Vendor shall implement CRM Integration by 15 April 2026\", \"classification\": \"IN_SCOPE\", \"source_sentence\": \"CRM Integration development has been completed and handed over to the QA team for system testing.\"}, {\"activity\": \"Analytics Dashboard\", \"confidence\": 90, \"match_type\": \"substring\", \"deliverable\": \"The Vendor shall develop an Analytics Dashboard\", \"classification\": \"IN_SCOPE\", \"source_sentence\": \"Development of the Analytics Dashboard is progressing well and is estimated to be around 60% complete.\"}, {\"activity\": \"UAT\", \"confidence\": 90, \"match_type\": \"substring\", \"deliverable\": \"The Vendor shall conduct UAT by 15 May 2026\", \"classification\": \"IN_SCOPE\", \"source_sentence\": \"User Acceptance Testing (UAT) has been rescheduled because dependent integration activities have not yet finished.\"}, {\"activity\": \"Production Deployment (Go Live)\", \"confidence\": 90, \"match_type\": \"substring\", \"deliverable\": \"The Vendor shall perform Production Deployment (Go Live) on...\", \"classification\": \"IN_SCOPE\", \"source_sentence\": \"The Go Live schedule may require revision if the current infrastructure dependencies are not resolved during the coming week.\"}, {\"activity\": \"Knowledge Transfer\", \"confidence\": 90, \"match_type\": \"substring\", \"deliverable\": \"The Vendor shall provide Knowledge Transfer by 05 July 2026\", \"classification\": \"IN_SCOPE\", \"source_sentence\": \"Knowledge Transfer sessions will be finalized after confirmation of the deployment timeline.\"}]}, \"timeline\": {\"deliverables\": [{\"risk\": \"HIGH\", \"blockers\": [\"MoM Evidence: Configuration of Azure AD Single Sign-On is currently on hold because VPN connectivity and API credentials from the client are still pending.\\nAnalysis: The configuration of Azure AD SSO is currently on hold (blocked) due to pending customer dependencies (VPN connectivity and API credentials).\"], \"delay_days\": 0, \"deliverable\": \"The Vendor shall configure Azure AD SSO by 25 April 2026\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"BLOCKED\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"MoM Evidence: Client to enable VPN connectivity for integration testing.\\nAnalysis: Providing VPN connectivity is an explicit contractual customer responsibility listed under project Assumptions.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide VPN connectivity\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"MoM Evidence: Client to provide API credentials before the next review meeting.\\nAnalysis: Providing API credentials is an explicit contractual customer responsibility listed under project Assumptions.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide API credentials\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}, {\"risk\": \"MEDIUM\", \"blockers\": [\"MoM Evidence: The client team agreed to provide API credentials, VPN access, and production environment details before the next project review.\\nAnalysis: Production environment details map to the customer\'s responsibility to provide \'required infrastructure before implementation\' as outlined in the baseline Assumptions.\"], \"delay_days\": 0, \"deliverable\": \"Customer shall provide required infrastructure before...\", \"expected_date\": \"Unknown\", \"current_status\": \"Blocked\", \"dependency_status\": \"DEPENDENCY\"}]}, \"out_of_scope\": {\"activities\": [{\"reason\": \"MoM Evidence: During the meeting, the client requested SAP Integration with the existing ERP platform.\\nAnalysis: SAP Integration is not listed in the approved Project Scope, which only outlines CRM Integration and Azure AD SSO.\", \"activity\": \"SAP Integration\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"SAP Integration\"}, {\"reason\": \"MoM Evidence: The client also requested Android and iOS mobile applications to enable field engineers to access the portal remotely.\\nAnalysis: The contract specifies a web-based Internal Support Portal. Adding Android and iOS mobile applications represents a major unapproved scope addition.\", \"activity\": \"Mobile Applications\", \"confidence\": 90, \"classification\": \"OUT_OF_SCOPE\", \"similar_deliverable\": \"Mobile Applications\"}, {\"reason\": \"