  `is_out_of_scope` tinyint(1) DEFAULT NULL,
  `risk_score` int DEFAULT '0',
  `risk_level` enum('LOW','MEDIUM','HIGH','CRITICAL') COLLATE utf8mb4_unicode_ci DEFAULT 'LOW',
