INSERT INTO `tracker_items` VALUES (1,6,7,'ACTIVITY',NULL,'Evaluate SAP Integration Request',1,80,'HIGH','SCOPE_CREEP',0.9500,'Activity: Evaluate SAP Integration Request\nThe activity involves evaluating an \'SAP Integration Request\'. SAP Integration is not mentioned in the approved baseline scope (the only approved integration is \'CRM Integration\'). According to the Change Control section, any work beyond the approved scope requires a formal Change Request approval, making this activity an unapproved out-of-scope request. (Confidence: 95%)',1,'OPEN','2026-07-25 11:31:33',NULL,NULL,NULL),(2,6,7,'ACTIVITY',NULL,'Review Mobile Applications Request',1,80,'HIGH','SCOPE_CREEP',0.9500,'Activity: Review Mobile Applications Request\nThe activity \'Review Mobile Applications Request\' directly relates to native mobile applications. The provided baseline context explicitly excludes \'Native Android and iOS applications\' from the project scope. Reviewing or implementing mobile applications introduces a significant risk of scope creep, and any work beyond the approved scope requires a formal Change Request approval. (Confidence: 95%)',1,'OPEN','2026-07-25 11:31:48',NULL,NULL,NULL),(3,6,7,'ACTIVITY',NULL,'Evaluate Voice Bot Proposal',1,80,'HIGH','SCOPE_CREEP',0.9500,'Activity: Evaluate Voice Bot Proposal\nThe baseline context explicitly states that \'Voice Bot implementation is out of scope.\' Evaluating a Voice Bot proposal introduces activities related to an excluded item, posing a high risk of scope creep. According to the baseline, any work beyond the approved scope requires a formal Change Request approval. (Confidence: 95%)',1,'OPEN','2026-07-25 11:32:44',NULL,NULL,NULL),(4,6,7,'ACTIVITY',NULL,'Analytics Dashboard Development',1,80,'HIGH','SCOPE_CREEP',0.9000,'Activity: Analytics Dashboard Development\nAnalytics Dashboard Development is not listed within the defined project scope in the baseline document. (Confidence: 90%)',1,'OPEN','2026-07-26 09:58:28',NULL,NULL,NULL),(5,6,7,'ACTIVITY',NULL,'SAP Integration Request Assessment',1,80,'HIGH','SCOPE_CREEP',0.9000,'Activity: SAP Integration Request Assessment\nSAP Integration is not included in the defined project scope. (Confidence: 90%)',1,'OPEN','2026-07-26 09:58:49',NULL,NULL,NULL),(6,6,7,'ACTIVITY',NULL,'Mobile Applications Request Review',1,80,'HIGH','SCOPE_CREEP',0.9000,'Activity: Mobile Applications Request Review\nThe baseline project scope specifies a web-based portal; mobile applications are out of scope. (Confidence: 90%)',1,'OPEN','2026-07-26 09:59:12',NULL,NULL,NULL),(7,6,7,'ACTIVITY',NULL,'Voice Bot Capability Evaluation',1,80,'HIGH','SCOPE_CREEP',0.9000,'Activity: Voice Bot Capability Evaluation\nVoice Bot functionality is not part of the defined project scope, which only includes AI Knowledge Search. (Confidence: 90%)',1,'OPEN','2026-07-26 09:59:29',NULL,NULL,NULL),(8,6,7,'ACTION_ITEM',NULL,'UAT - 15 May 2026',0,65,'MEDIUM','DELAY',1.0000,'Deliverable: UAT - 15 May 2026\nStatus: Delayed. Blockers: Rescheduling UAT directly affects the project\'s baseline milestone of 15 May 2026.',1,'OPEN','2026-07-26 09:59:53',NULL,NULL,NULL),(9,6,7,'ACTION_ITEM',NULL,'Go Live - 30 June 2026',0,65,'HIGH','DELAY',1.0000,'Deliverable: Go Live - 30 June 2026\nStatus: Delayed. Blockers: Revising the Go Live schedule indicates a risk of delaying the agreed milestone of 30 June 2026.',1,'OPEN','2026-07-26 09:59:53',NULL,NULL,NULL),(10,6,7,'ACTION_ITEM',NULL,'Customer shall provide API credentials.',0,65,'MEDIUM','DELAY',1.0000,'Deliverable: Customer shall provide API credentials.\nStatus: Blocked. Blockers: This activity relies on the customer fulfilling an explicit project assumption.',1,'OPEN','2026-07-26 09:59:53',NULL,NULL,NULL),(11,6,7,'ACTION_ITEM',NULL,'Customer shall provide VPN connectivity.',0,65,'MEDIUM','DELAY',1.0000,'Deliverable: Customer shall provide VPN connectivity.\nStatus: Blocked. Blockers: Fulfilling VPN connectivity is a critical customer assumption required before